private void commitMaxData(long maximum) {
    if (maximum > sendMaxData) {
        final long previous = sendMaxData;
        sendMaxData = maximum;
        journal.add(() -> sendMaxData = previous);
    }
}

private void commitMaxStreams(long maximum, boolean bidirectional) {
    if (bidirectional) {
