private Stream reference(long id, boolean receive) {
    int mod = (int) (id & 3);
    long index = id >>> 2;
    if (receive) {
        // Receive references accept client-initiated ids and already open server bidi ids.
        if (mod == 0) {
            if (index >= clientBidiLimit) throw new Fail(STREAM_LIMIT, 0);
            openPeer(index, true);
        } else if (mod == 2) {
            if (index >= clientUniLimit) throw new Fail(STREAM_LIMIT, 0);
            openPeer(index, false);
        } else if (mod == 1) {
            if (index >= localBidi) throw new Fail(STREAM_STATE, 0);
        } else {
            throw new Fail(STREAM_STATE, 0);
        }
    } else if (mod == 0) {
        // Send references accept client bidi ids and already open server bidi/uni ids.
        if (index >= clientBidiLimit) throw new Fail(STREAM_LIMIT, 0);
        openPeer(index, true);
    } else if (mod == 1) {
        if (index >= localBidi) throw new Fail(STREAM_STATE, 0);
    } else if (mod == 3) {
        if (index >= localUni) throw new Fail(STREAM_STATE, 0);
    } else {
        throw new Fail(STREAM_STATE, 0);
    }
    return entry(id);
}

private void openPeer(long index, boolean bidirectional) {
    long candidate = index + 1;
    if (bidirectional) {
        if (candidate > openedBidi) {
            final long previous = openedBidi;
            openedBidi = candidate;
            journal.add(() -> openedBidi = previous);
        }
    } else if (candidate > openedUni) {
        final long previous = openedUni;
        openedUni = candidate;
        journal.add(() -> openedUni = previous);
    }
}

